const config = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "postgresql",
  "inlineSchema": "// ─────────────────────────────────────────────────────────────────────────────\n// Carkhodro — Auto Spare Parts E-Commerce\n// PostgreSQL · Prisma ORM\n// ─────────────────────────────────────────────────────────────────────────────\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../generated/prisma_client\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// ENUMS\n// ─────────────────────────────────────────────────────────────────────────────\n\nenum UserRole {\n  RETAIL\n  WHOLESALE\n  ADMIN // full back-office access\n  SUPPORT // read-only order/customer access\n}\n\n/// Audience filter for a bulk SMS blast — mirrors the RETAIL/WHOLESALE split\n/// used everywhere else for pricing, with ALL meaning both.\nenum SmsTargetRole {\n  RETAIL\n  WHOLESALE\n  ALL\n}\n\nenum SmsCampaignStatus {\n  PENDING\n  SENT\n  PARTIAL // some recipients failed\n  FAILED\n}\n\n/// Wholesale-order lifecycle, surfaced in the partner dashboard's order list and\n/// status filter. Ordered roughly by progression; cancellation/archive are\n/// terminal side-states. Persian labels live in `src/lib/order-labels.ts`.\nenum OrderStatus {\n  NEW // سفارش جدید — just submitted\n  AWAITING_CONFIRMATION // در انتظار تایید — pending shop review\n  CONFIRMED_AWAITING_PAYMENT // تایید شده و در انتظار پرداخت\n  PAID // پرداخت شده توسط مشتری\n  SHIPPED // ارسال سفارش — handed to carrier\n  COMPLETED // اتمام فاکتور — invoice closed\n  CANCELLED_BY_CUSTOMER // لغو شده توسط مشتری\n  CANCELLED_BY_MANAGER // لغو توسط مدیرفروشگاه\n  ARCHIVED // آرشیو\n}\n\n/// Direction of a support message relative to the partner (who owns the thread).\nenum MessageDirection {\n  INBOUND // received by the partner (sent by the support desk)\n  OUTBOUND // sent by the partner to support\n}\n\nenum PaymentMethod {\n  ONLINE // IPG redirect\n  COD // cash on delivery\n}\n\nenum PaymentStatus {\n  PENDING\n  PAID\n  FAILED\n  REFUNDED\n}\n\n/// How a redeemable coupon reduces the order total.\nenum DiscountType {\n  PERCENTAGE // درصدی — value is 0–100\n  FIXED_AMOUNT // مبلغی — value is Toman\n  FREE_SHIPPING // ارسال رایگان — value ignored\n}\n\n/// What catalogue slice a discount code applies to.\n/// ALL ignores `scopeIds`. For other types, empty `scopeIds` also means all products.\nenum DiscountScopeType {\n  ALL // همه محصولات — scopeIds ignored / stored empty\n  CATEGORY // دسته‌بندی — scopeIds are Category.id as strings\n  BRAND // برند قطعه — scopeIds are PartsBrand.id as strings\n  CAR_BRAND // برند خودرو — scopeIds are CarBrand.id as strings\n  CAR_MODEL // مدل خودرو — scopeIds are CarModel.id as strings\n  PRODUCT // محصول — scopeIds are Product.id (cuid)\n}\n\n/// Which storefront audience may redeem a discount code.\n/// BOTH = retail customers and wholesale partners.\nenum DiscountTargetUserType {\n  RETAIL\n  WHOLESALE\n  BOTH\n}\n\n/// Which footer column a managed link belongs to.\nenum FooterLinkGroup {\n  QUICK // لینک‌های سریع\n  CATEGORY // دسته‌بندی‌ها\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// REFERENCE DATA\n// ─────────────────────────────────────────────────────────────────────────────\n\n/// The 31 Iranian provinces — seeded once; never deleted.\nmodel Province {\n  id        Int      @id @default(autoincrement())\n  name      String   @unique\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  cities City[]\n\n  @@map(\"provinces\")\n}\n\n/// Cities nested under a province — seeded from a standard list; admin can add more.\nmodel City {\n  id         Int      @id @default(autoincrement())\n  provinceId Int      @map(\"province_id\")\n  name       String\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n\n  province  Province  @relation(fields: [provinceId], references: [id])\n  addresses Address[]\n\n  @@unique([provinceId, name])\n  @@index([provinceId])\n  @@map(\"cities\")\n}\n\n/// Top-level navigation links — managed by admin; front end caches and revalidates.\nmodel NavLink {\n  id        Int      @id @default(autoincrement())\n  href      String   @unique\n  label     String\n  sortOrder Int      @default(0) @map(\"sort_order\")\n  isActive  Boolean  @default(true) @map(\"is_active\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  @@map(\"nav_links\")\n}\n\n/// Footer column links — «لینک‌های سریع» / «دسته‌بندی‌ها», managed in admin.\nmodel FooterLink {\n  id        Int             @id @default(autoincrement())\n  group     FooterLinkGroup\n  href      String\n  label     String\n  sortOrder Int             @default(0) @map(\"sort_order\")\n  isActive  Boolean         @default(true) @map(\"is_active\")\n  createdAt DateTime        @default(now()) @map(\"created_at\")\n  updatedAt DateTime        @updatedAt @map(\"updated_at\")\n\n  @@index([group, sortOrder])\n  @@map(\"footer_links\")\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// AUTHENTICATION\n// ─────────────────────────────────────────────────────────────────────────────\n\nmodel User {\n  id              String    @id @default(cuid())\n  /// Iranian mobile format: 09XXXXXXXXX (11 digits)\n  phoneNumber     String    @unique @map(\"phone_number\")\n  firstName       String    @map(\"first_name\")\n  lastName        String    @map(\"last_name\")\n  role            UserRole  @default(RETAIL)\n  /// Set to true after the first successful OTP verification\n  isVerified      Boolean   @default(false) @map(\"is_verified\")\n  /// When false, the user cannot log in (storefront OTP or admin password).\n  isActive        Boolean   @default(true) @map(\"is_active\")\n  /// Wholesale customers must supply a shop/business name\n  shopName        String?   @map(\"shop_name\")\n  birthDate       DateTime? @map(\"birth_date\")\n  profileImage    String?   @map(\"profile_image\")\n  /// Partner's running ledger balance with the shop, in the same magnitude as\n  /// product prices (Toman). Shown as «مانده حساب» on the dashboard.\n  accountBalance  BigInt    @default(0) @map(\"account_balance\")\n  /// Who referred this partner («معرف») — free text captured on the profile.\n  referredBy      String?   @map(\"referred_by\")\n  /// The partner's line of business («زمینه فعالیت») — free text.\n  activityField   String?   @map(\"activity_field\")\n  /// Short, unique partner/affiliate code («کد اختصاصی») — null for retail users.\n  partnerCode     String?   @unique @map(\"partner_code\")\n  /// Admin login username — only set for ADMIN-role users; storefront customers\n  /// authenticate with SMS OTP and never get one.\n  username        String?   @unique\n  /// Scrypt password hash — only set for admin/back-office logins (ADMIN role).\n  /// Storefront customers keep authenticating with SMS OTP and never get one.\n  passwordHash    String?   @map(\"password_hash\")\n  /// Grants access to security-sensitive system configuration. This is kept\n  /// separate from ADMIN so future back-office accounts are least-privileged.\n  isSuperAdmin    Boolean   @default(false) @map(\"is_super_admin\")\n  /// Hesabfa contact `Code` — unique link key for two-way contact sync.\n  hesabfaCode     String?   @unique @map(\"hesabfa_code\")\n  /// Hesabfa internal numeric contact Id (webhook ObjectIdList).\n  hesabfaId       Int?      @unique @map(\"hesabfa_id\")\n  /// Last successful Hesabfa contact sync timestamp.\n  hesabfaSyncedAt DateTime? @map(\"hesabfa_synced_at\")\n  createdAt       DateTime  @default(now()) @map(\"created_at\")\n  updatedAt       DateTime  @updatedAt @map(\"updated_at\")\n\n  addresses          Address[]\n  sessions           Session[]\n  orders             Order[]\n  reviews            Review[]\n  cart               Cart?\n  wishlist           WishlistItem[]\n  compareItems       CompareItem[]\n  supportMessages    SupportMessage[]\n  orderSurveys       OrderSurvey[]\n  priceListRequests  PriceListRequest[]\n  productSuggestions ProductSuggestion[]\n  smsCampaigns       SmsCampaign[]\n\n  @@index([phoneNumber])\n  @@index([isActive])\n  @@index([hesabfaCode])\n  @@map(\"users\")\n}\n\n/// One active OTP per phone number — upserted on every send request.\nmodel OtpSession {\n  id          String   @id @default(cuid())\n  phoneNumber String   @unique @map(\"phone_number\")\n  /// Bcrypt-hashed in production; store plain only in dev/test\n  codeHash    String   @map(\"code_hash\")\n  /// Hard cutoff — reject even if code matches after this time\n  expiresAt   DateTime @map(\"expires_at\")\n  /// Count repeated send attempts to enable rate-limiting\n  attempts    Int      @default(0)\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n\n  @@index([phoneNumber])\n  @@map(\"otp_sessions\")\n}\n\n/// Server-issued session token — created after OTP is consumed.\nmodel Session {\n  id        String   @id @default(cuid())\n  token     String   @unique\n  userId    String   @map(\"user_id\")\n  expiresAt DateTime @map(\"expires_at\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([expiresAt])\n  @@map(\"sessions\")\n}\n\n/// User delivery addresses — one user may save many; at most one isDefault.\nmodel Address {\n  id         String   @id @default(cuid())\n  userId     String   @map(\"user_id\")\n  cityId     Int      @map(\"city_id\")\n  street     String\n  postalCode String   @map(\"postal_code\")\n  isDefault  Boolean  @default(false) @map(\"is_default\")\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n  updatedAt  DateTime @updatedAt @map(\"updated_at\")\n\n  user   User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  city   City    @relation(fields: [cityId], references: [id])\n  orders Order[]\n\n  @@index([userId])\n  @@index([cityId])\n  @@map(\"addresses\")\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// CATALOGUE — CAR TAXONOMY\n// ─────────────────────────────────────────────────────────────────────────────\n\n/// Automobile manufacturers / vehicle brands (“برند خودرو”): ایران‌خودرو, سایپا, تویوتا, …\nmodel CarBrand {\n  id           Int      @id @default(autoincrement())\n  name         String   @unique\n  /// URL-safe slug, e.g. \"iran-khodro\"\n  slug         String   @unique\n  logoImage    String?  @map(\"logo_image\")\n  /// Denormalized counter — refreshed by a background job or DB trigger\n  productCount Int      @default(0) @map(\"product_count\")\n  isActive     Boolean  @default(true) @map(\"is_active\")\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n  updatedAt    DateTime @updatedAt @map(\"updated_at\")\n\n  carModels CarModel[]\n\n  @@index([isActive])\n  @@map(\"car_brands\")\n}\n\n/// Specific vehicle models (“مدل خودرو”) — FK carBrandId → car_brands.id\nmodel CarModel {\n  id         Int      @id @default(autoincrement())\n  carBrandId Int      @map(\"car_brand_id\")\n  name       String\n  image      String?\n  isActive   Boolean  @default(true) @map(\"is_active\")\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n  updatedAt  DateTime @updatedAt @map(\"updated_at\")\n\n  carBrand        CarBrand               @relation(fields: [carBrandId], references: [id])\n  compatibilities ProductCompatibility[]\n\n  @@index([carBrandId])\n  @@index([isActive])\n  @@map(\"car_models\")\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// CATALOGUE — PARTS\n// ─────────────────────────────────────────────────────────────────────────────\n\n/// Spare-parts suppliers / manufacturers: بوش, NGK, ایساکو, …\n/// Distinct from CarBrand — a Bosch brake pad fits a Toyota, not made by Toyota.\nmodel PartsBrand {\n  id        Int      @id @default(autoincrement())\n  name      String   @unique\n  /// URL / filter slug, e.g. \"bosch\", \"ngk\"\n  slug      String   @unique\n  logoImage String?  @map(\"logo_image\")\n  isActive  Boolean  @default(true) @map(\"is_active\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  products Product[]\n\n  @@index([isActive])\n  @@map(\"parts_brands\")\n}\n\n/// Product category: موتور و قطعات, ترمز و تعلیق, برق و روشنایی, …\nmodel Category {\n  id           Int      @id @default(autoincrement())\n  /// URL / filter slug, e.g. \"engine\", \"brake\"\n  key          String   @unique\n  name         String\n  image        String   @default(\"/logo.png\")\n  sortOrder    Int      @default(0) @map(\"sort_order\")\n  /// Denormalized counter — refreshed by a background job or DB trigger\n  productCount Int      @default(0) @map(\"product_count\")\n  isActive     Boolean  @default(true) @map(\"is_active\")\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n  updatedAt    DateTime @updatedAt @map(\"updated_at\")\n\n  products Product[]\n\n  @@index([isActive])\n  @@map(\"categories\")\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// PRODUCT\n// ─────────────────────────────────────────────────────────────────────────────\n\nmodel Product {\n  id           String @id @default(cuid())\n  /// Human-readable part number, e.g. \"BSH-ENG-206-001\"\n  sku          String @unique\n  name         String\n  partsBrandId Int    @map(\"parts_brand_id\")\n  categoryId   Int    @map(\"category_id\")\n\n  // ── Pricing ────────────────────────────────────────────────────────────────\n  /// Base wholesale price in Toman.\n  wholesalePrice        BigInt  @map(\"wholesale_price\")\n  /// Optional purchase / cost price in Toman (Hesabfa `BuyPrice`).\n  buyPrice              BigInt? @map(\"buy_price\")\n  /// Percentage deducted for WHOLESALE users (0–100).\n  /// wholesaleFinal = wholesalePrice × (1 − wholesaleDiscountPct / 100)\n  wholesaleDiscountPct  Decimal @default(0) @map(\"wholesale_discount_pct\") @db.Decimal(5, 2)\n  /// Percentage added to wholesalePrice to derive the retail list price (1–100).\n  /// retailPrice = wholesalePrice × (1 + retailPriceDiffPct / 100)\n  retailPriceDiffPct    Decimal @default(25) @map(\"retail_price_diff_pct\") @db.Decimal(5, 2)\n  /// Percentage deducted from retailPrice for RETAIL users (0–100).\n  /// retailFinal = retailPrice × (1 − retailDiscountPct / 100)\n  retailDiscountPct     Decimal @default(0) @map(\"retail_discount_pct\") @db.Decimal(5, 2)\n  isOffer               Boolean @default(false) @map(\"is_offer\")\n  /// When true, retail/guest users see “Call for Price” instead of the price and cannot purchase.\n  callForPriceRetail    Boolean @default(false) @map(\"call_for_price_retail\")\n  /// When true, wholesale partners see “Call for Price” instead of the price and cannot purchase.\n  callForPriceWholesale Boolean @default(false) @map(\"call_for_price_wholesale\")\n\n  // ── Hesabfa accounting link ───────────────────────────────────────────────\n  /// Hesabfa item `Code` — unique link key for two-way product sync.\n  hesabfaCode  String?   @unique @map(\"hesabfa_code\")\n  /// Hesabfa internal numeric item Id (webhook ObjectIdList / deletes).\n  hesabfaId    Int?      @unique @map(\"hesabfa_id\")\n  /// Timestamp of the last successful Hesabfa product sync.\n  lastSyncedAt DateTime? @map(\"last_synced_at\")\n\n  // ── Inventory ─────────────────────────────────────────────────────────────\n  stock Int @default(0)\n\n  // ── Physical / logistics details (managed by local admin) ─────────────────\n  /// Country of origin, e.g. \"آلمان\", \"ژاپن\", \"ایران\"\n  origin         String?\n  /// Units per retail pack (e.g. spark plugs come in sets of 4)\n  packQuantity   Int     @default(1) @map(\"pack_quantity\")\n  /// Retail packs per master carton — for wholesale order sizing\n  cartonQuantity Int     @default(1) @map(\"carton_quantity\")\n  /// Display unit label on the storefront (e.g. \"عدد\", \"بسته\", \"متر\")\n  unit           String  @default(\"عدد\")\n  /// true = OEM / genuine part; false = aftermarket\n  isOriginal     Boolean @default(true) @map(\"is_original\")\n\n  // ── Content (managed by local admin) ──────────────────────────────────────\n  mainImage   String? @map(\"main_image\")\n  description String? @db.Text\n\n  // ── Fuzzy full-text search ────────────────────────────────────────────────\n  /// Denormalized, normalized search document (name + sku + origin + parts-brand\n  /// + category + compatible car models). DB-maintained via triggers — never\n  /// written from application code. Queried with pg_trgm for typo-tolerant search.\n  searchText String? @map(\"search_text\")\n\n  // ── Analytics ──────────────────────────────────────────────────────────────\n  viewCount   Int     @default(0) @map(\"view_count\")\n  saleCount   Int     @default(0) @map(\"sale_count\")\n  /// Denormalized average star rating (1.00–5.00) — recomputed on each new review\n  ratingAvg   Decimal @default(0) @map(\"rating_avg\") @db.Decimal(3, 2)\n  reviewCount Int     @default(0) @map(\"review_count\")\n\n  isActive  Boolean  @default(true) @map(\"is_active\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  partsBrand      PartsBrand             @relation(fields: [partsBrandId], references: [id])\n  category        Category               @relation(fields: [categoryId], references: [id])\n  images          ProductImage[]\n  compatibilities ProductCompatibility[]\n  reviews         Review[]\n  cartItems       CartItem[]\n  orderItems      OrderItem[]\n  wishlistedBy    WishlistItem[]\n  comparedBy      CompareItem[]\n\n  @@index([sku])\n  @@index([hesabfaCode])\n  @@index([categoryId])\n  @@index([partsBrandId])\n  @@index([isActive, isOffer])\n  @@index([saleCount])\n  @@index([viewCount])\n  @@index([searchText(ops: raw(\"gin_trgm_ops\"))], type: Gin, map: \"products_search_text_trgm_idx\")\n  @@map(\"products\")\n}\n\n/// Additional product gallery images (beyond mainImage).\nmodel ProductImage {\n  id        String  @id @default(cuid())\n  productId String  @map(\"product_id\")\n  url       String\n  alt       String?\n  sortOrder Int     @default(0) @map(\"sort_order\")\n\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@index([productId])\n  @@map(\"product_images\")\n}\n\n/// Many-to-many: a spare part can be compatible with multiple car models.\nmodel ProductCompatibility {\n  id         String @id @default(cuid())\n  productId  String @map(\"product_id\")\n  carModelId Int    @map(\"car_model_id\")\n\n  product  Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  carModel CarModel @relation(fields: [carModelId], references: [id], onDelete: Cascade)\n\n  @@unique([productId, carModelId])\n  @@index([productId])\n  @@index([carModelId])\n  @@map(\"product_compatibilities\")\n}\n\n/// Customer review and star rating on a product.\nmodel Review {\n  id                 String    @id @default(cuid())\n  productId          String    @map(\"product_id\")\n  /// Nullable — preserves display name even if the user account is deleted\n  userId             String?   @map(\"user_id\")\n  authorName         String    @map(\"author_name\")\n  /// 1–5\n  rating             Int\n  text               String    @db.Text\n  /// true only when the author has a completed order containing this product\n  isVerifiedPurchase Boolean   @default(false) @map(\"is_verified_purchase\")\n  /// Admin-side read flag for the communications inbox (defaults unread for new reviews).\n  isRead             Boolean   @default(false) @map(\"is_read\")\n  /// When true, the review is hidden from the storefront but kept in the admin inbox.\n  isHidden           Boolean   @default(false) @map(\"is_hidden\")\n  /// Optional public reply from the shop, shown under the review on the PDP.\n  adminReply         String?   @map(\"admin_reply\") @db.Text\n  repliedAt          DateTime? @map(\"replied_at\")\n  createdAt          DateTime  @default(now()) @map(\"created_at\")\n\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n  user    User?   @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  @@index([productId])\n  @@index([userId])\n  @@index([isRead])\n  @@index([isHidden])\n  @@map(\"reviews\")\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// CART\n// ─────────────────────────────────────────────────────────────────────────────\n\n/// One active cart per user — created lazily on first add-to-cart action.\nmodel Cart {\n  id        String   @id @default(cuid())\n  userId    String   @unique @map(\"user_id\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  user  User       @relation(fields: [userId], references: [id], onDelete: Cascade)\n  items CartItem[]\n\n  @@map(\"carts\")\n}\n\nmodel CartItem {\n  id        String   @id @default(cuid())\n  cartId    String   @map(\"cart_id\")\n  productId String   @map(\"product_id\")\n  quantity  Int      @default(1)\n  addedAt   DateTime @default(now()) @map(\"added_at\")\n\n  cart    Cart    @relation(fields: [cartId], references: [id], onDelete: Cascade)\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@unique([cartId, productId])\n  @@index([cartId])\n  @@map(\"cart_items\")\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// WISHLIST & COMPARE\n// ─────────────────────────────────────────────────────────────────────────────\n\n/// A product a user has saved for later. Independent of the cart — purely a\n/// per-user bookmark. One row per (user, product); re-adding is a no-op.\nmodel WishlistItem {\n  id        String   @id @default(cuid())\n  userId    String   @map(\"user_id\")\n  productId String   @map(\"product_id\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, productId])\n  @@index([userId])\n  @@index([productId])\n  @@map(\"wishlist_items\")\n}\n\n/// A product a user has added to their side-by-side compare list. Same shape as\n/// the wishlist but a separate concern; the app caps the active list size.\nmodel CompareItem {\n  id        String   @id @default(cuid())\n  userId    String   @map(\"user_id\")\n  productId String   @map(\"product_id\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, productId])\n  @@index([userId])\n  @@index([productId])\n  @@map(\"compare_items\")\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// FAQ\n// ─────────────────────────────────────────────────────────────────────────────\n\n/// Blog post categories — admin-managed taxonomy for /blog filtering.\nmodel PostCategory {\n  id              Int      @id @default(autoincrement())\n  /// URL-safe slug, e.g. \"maintenance\"\n  slug            String   @unique\n  name            String\n  description     String?  @db.Text\n  /// Optional SEO overrides for category listing pages.\n  metaTitle       String?  @map(\"meta_title\")\n  metaDescription String?  @map(\"meta_description\") @db.Text\n  sortOrder       Int      @default(0) @map(\"sort_order\")\n  isActive        Boolean  @default(true) @map(\"is_active\")\n  createdAt       DateTime @default(now()) @map(\"created_at\")\n  updatedAt       DateTime @updatedAt @map(\"updated_at\")\n\n  posts Post[]\n\n  @@index([isActive])\n  @@index([sortOrder])\n  @@map(\"post_categories\")\n}\n\n/// Blog posts — authored by admin; displayed on /blog and /blog/[slug].\nmodel Post {\n  id          Int      @id @default(autoincrement())\n  /// URL-safe slug, e.g. \"oil-change-guide\"\n  slug        String   @unique\n  title       String\n  excerpt     String   @db.Text\n  /// HTML body — admin-authored content, never direct user input.\n  body        String   @db.Text\n  coverImage  String   @map(\"cover_image\")\n  author      String\n  tags        String[]\n  /// Estimated read time in minutes\n  readTime    Int      @map(\"read_time\")\n  publishedAt DateTime @map(\"published_at\")\n  isPublished Boolean  @default(true) @map(\"is_published\")\n  categoryId  Int?     @map(\"category_id\")\n\n  // ── SEO / Open Graph ───────────────────────────────────────────────────────\n  metaTitle       String? @map(\"meta_title\")\n  metaDescription String? @map(\"meta_description\") @db.Text\n  metaKeywords    String? @map(\"meta_keywords\")\n  ogTitle         String? @map(\"og_title\")\n  ogDescription   String? @map(\"og_description\") @db.Text\n  /// Falls back to coverImage when null.\n  ogImage         String? @map(\"og_image\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  category PostCategory? @relation(fields: [categoryId], references: [id], onDelete: SetNull)\n\n  @@index([publishedAt])\n  @@index([isPublished])\n  @@index([categoryId])\n  @@map(\"posts\")\n}\n\n/// Frequently-asked questions — admin-managed; displayed on the /faq page.\nmodel Faq {\n  id        Int      @id @default(autoincrement())\n  question  String\n  answer    String   @db.Text\n  sortOrder Int      @default(0) @map(\"sort_order\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  @@map(\"faqs\")\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// SITE SETTINGS — singleton row, admin-managed\n// ─────────────────────────────────────────────────────────────────────────────\n\n/// Dynamic site info shown across the storefront (footer/contact/etc). Always a\n/// single row — the app upserts `id = 1`.\nmodel SiteSetting {\n  id                Int      @id @default(1)\n  /// Shown to guests and RETAIL customers.\n  retailPhone1      String?  @map(\"retail_phone_1\")\n  retailPhone2      String?  @map(\"retail_phone_2\")\n  /// Shown only when a WHOLESALE user is logged in.\n  wholesalePhone1   String?  @map(\"wholesale_phone_1\")\n  wholesalePhone2   String?  @map(\"wholesale_phone_2\")\n  wholesalePhone3   String?  @map(\"wholesale_phone_3\")\n  wholesalePhone4   String?  @map(\"wholesale_phone_4\")\n  email             String?\n  address           String?  @db.Text\n  workingHours      String?  @map(\"working_hours\")\n  /// Short promo lines shown in the header top bar (e.g. trust badges).\n  headerPromo1      String?  @map(\"header_promo_1\")\n  headerPromo2      String?  @map(\"header_promo_2\")\n  /// Optional icon for promo line 1 — storage URL or emoji; no built-in default.\n  headerPromo1Icon  String?  @map(\"header_promo_1_icon\")\n  /// Optional icon for promo line 2 — storage URL or emoji; no built-in default.\n  headerPromo2Icon  String?  @map(\"header_promo_2_icon\")\n  aboutText         String?  @map(\"about_text\") @db.Text\n  /// Footer trust badges (icon / title / description) — four fixed slots.\n  footerTrust1Icon  String?  @map(\"footer_trust_1_icon\")\n  footerTrust1Title String?  @map(\"footer_trust_1_title\")\n  footerTrust1Desc  String?  @map(\"footer_trust_1_desc\")\n  footerTrust2Icon  String?  @map(\"footer_trust_2_icon\")\n  footerTrust2Title String?  @map(\"footer_trust_2_title\")\n  footerTrust2Desc  String?  @map(\"footer_trust_2_desc\")\n  footerTrust3Icon  String?  @map(\"footer_trust_3_icon\")\n  footerTrust3Title String?  @map(\"footer_trust_3_title\")\n  footerTrust3Desc  String?  @map(\"footer_trust_3_desc\")\n  footerTrust4Icon  String?  @map(\"footer_trust_4_icon\")\n  footerTrust4Title String?  @map(\"footer_trust_4_title\")\n  footerTrust4Desc  String?  @map(\"footer_trust_4_desc\")\n  /// Homepage hero copy (static — images are managed via HeroBanner slides).\n  heroTitle         String?  @map(\"hero_title\")\n  heroDescription   String?  @map(\"hero_description\") @db.Text\n  heroButton1Text   String?  @map(\"hero_button1_text\")\n  heroButton1Href   String?  @map(\"hero_button1_href\")\n  heroButton2Text   String?  @map(\"hero_button2_text\")\n  heroButton2Href   String?  @map(\"hero_button2_href\")\n  /// Branding, default SEO, and analytics (admin-managed).\n  siteName          String?  @map(\"site_name\")\n  logoUrl           String?  @map(\"logo_url\")\n  faviconUrl        String?  @map(\"favicon_url\")\n  appleTouchIconUrl String?  @map(\"apple_touch_icon_url\")\n  metaTitle         String?  @map(\"meta_title\")\n  metaDescription   String?  @map(\"meta_description\") @db.Text\n  ogImageUrl        String?  @map(\"og_image_url\")\n  copyrightText     String?  @map(\"copyright_text\")\n  /// Google Analytics (`G-…` / `UA-…`) or Google Tag Manager (`GTM-…`) container ID.\n  analyticsId       String?  @map(\"analytics_id\")\n  updatedAt         DateTime @updatedAt @map(\"updated_at\")\n\n  @@map(\"site_settings\")\n}\n\n/// Encrypted integration configuration. The application only ever decrypts\n/// this singleton inside its server-only settings DAL.\nmodel SystemSetting {\n  id              Int      @id @default(1)\n  encryptedConfig String   @map(\"encrypted_config\") @db.Text\n  updatedById     String?  @map(\"updated_by_id\")\n  createdAt       DateTime @default(now()) @map(\"created_at\")\n  updatedAt       DateTime @updatedAt @map(\"updated_at\")\n\n  @@map(\"system_settings\")\n}\n\n/// Terms & rules page content — singleton row (`id = 1`), admin-edited via TipTap.\nmodel RulesContent {\n  id           Int      @id @default(1)\n  /// Line under the page title (e.g. last-updated note).\n  updatedLabel String?  @map(\"updated_label\")\n  /// Amber intro banner text on /rules.\n  intro        String?  @db.Text\n  /// Main rules body HTML — admin-authored via TipTap.\n  body         String   @default(\"\") @db.Text\n  updatedAt    DateTime @updatedAt @map(\"updated_at\")\n\n  @@map(\"rules_content\")\n}\n\n/// Admin-managed social media links — shown in the footer and contact page.\nmodel SocialLink {\n  id        Int      @id @default(autoincrement())\n  label     String\n  url       String\n  /// Display icon — typically an emoji (e.g. 📸 for Instagram).\n  icon      String\n  sortOrder Int      @default(0) @map(\"sort_order\")\n  isActive  Boolean  @default(true) @map(\"is_active\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  @@index([sortOrder])\n  @@map(\"social_links\")\n}\n\n/// Homepage hero image slides — copy/CTAs live on SiteSetting; only images rotate.\nmodel HeroBanner {\n  id        Int      @id @default(autoincrement())\n  imageUrl  String   @map(\"image_url\")\n  sortOrder Int      @default(0) @map(\"sort_order\")\n  isActive  Boolean  @default(true) @map(\"is_active\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  @@index([sortOrder])\n  @@map(\"hero_banners\")\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// BULK SMS MARKETING — admin-managed\n// ─────────────────────────────────────────────────────────────────────────────\n\n/// One row per bulk SMS blast the admin sends («ارسال گروهی پیامک»). Snapshot\n/// only — the recipient list itself isn't retained, just the counts, to keep\n/// this table cheap and avoid storing phone numbers redundantly.\nmodel SmsCampaign {\n  id             String            @id @default(cuid())\n  body           String            @db.Text\n  targetRole     SmsTargetRole     @map(\"target_role\")\n  recipientCount Int               @default(0) @map(\"recipient_count\")\n  successCount   Int               @default(0) @map(\"success_count\")\n  failedCount    Int               @default(0) @map(\"failed_count\")\n  status         SmsCampaignStatus @default(PENDING)\n  createdById    String?           @map(\"created_by_id\")\n  createdAt      DateTime          @default(now()) @map(\"created_at\")\n  completedAt    DateTime?         @map(\"completed_at\")\n\n  createdBy User? @relation(fields: [createdById], references: [id], onDelete: SetNull)\n\n  @@index([createdAt])\n  @@map(\"sms_campaigns\")\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// ORDERS\n// ─────────────────────────────────────────────────────────────────────────────\n\n/// Shipping methods and their current cost — editable by admin.\n/// `method` is a stable unique code (e.g. STANDARD, EXPRESS); free-form codes allowed.\nmodel ShippingOption {\n  id          String   @id @default(cuid())\n  method      String   @unique\n  label       String\n  description String?\n  cost        BigInt\n  isActive    Boolean  @default(true) @map(\"is_active\")\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n  updatedAt   DateTime @updatedAt @map(\"updated_at\")\n\n  orders Order[]\n\n  @@map(\"shipping_options\")\n}\n\nmodel Order {\n  id               String        @id @default(cuid())\n  /// Human-facing, sequential invoice number («شماره فاکتور») shown on the\n  /// partner's orders list and printable invoice — distinct from the cuid `id`.\n  orderNumber      Int           @unique @default(autoincrement()) @map(\"order_number\")\n  userId           String        @map(\"user_id\")\n  /// FK kept for history; address data also snapshotted below.\n  addressId        String        @map(\"address_id\")\n  shippingOptionId String        @map(\"shipping_option_id\")\n  status           OrderStatus   @default(NEW)\n  paymentMethod    PaymentMethod @map(\"payment_method\")\n  paymentStatus    PaymentStatus @default(PENDING) @map(\"payment_status\")\n  /// Free-text settlement terms chosen on the partner invoice (e.g. «چکی», «نقدی»,\n  /// «اعتباری»). Complements the coarse `paymentMethod` enum used by retail checkout.\n  paymentTerms     String?       @map(\"payment_terms\")\n\n  // ── Snapshotted delivery address ──────────────────────────────────────────\n  // Copied at checkout so later edits to the address row don't affect history.\n  snapshotProvince   String @map(\"snapshot_province\")\n  snapshotCity       String @map(\"snapshot_city\")\n  snapshotStreet     String @map(\"snapshot_street\")\n  snapshotPostalCode String @map(\"snapshot_postal_code\")\n\n  // ── Financials ─────────────────────────────────────────────────────────────\n  subtotal       BigInt  @map(\"subtotal\")\n  shippingCost   BigInt  @map(\"shipping_cost\")\n  /// VAT or other applicable tax collected on this order\n  taxAmount      BigInt  @default(0) @map(\"tax_amount\")\n  /// Coupon discount applied at checkout (Toman). 0 when no code was used.\n  discountAmount BigInt  @default(0) @map(\"discount_amount\")\n  /// Snapshot of the redeemed code string (kept even if the code row is deleted).\n  discountCode   String? @map(\"discount_code\")\n  discountCodeId String? @map(\"discount_code_id\")\n  /// subtotal + shippingCost + taxAmount − discountAmount (stored to prevent drift)\n  totalAmount    BigInt  @map(\"total_amount\")\n\n  notes        String?\n  trackingCode String? @map(\"tracking_code\")\n\n  /// Zibal IPG session id — set when an online payment is initiated.\n  paymentTrackId   BigInt? @map(\"payment_track_id\")\n  /// Bank reference number returned by Zibal after a successful verify.\n  paymentRefNumber String? @map(\"payment_ref_number\")\n\n  /// Hesabfa sales invoice `Number` — unique link key (never import unknown invoices).\n  hesabfaCode     String?   @unique @map(\"hesabfa_code\")\n  /// Hesabfa internal numeric invoice Id (webhook ObjectIdList).\n  hesabfaId       Int?      @unique @map(\"hesabfa_id\")\n  /// Last successful Hesabfa invoice sync timestamp.\n  hesabfaSyncedAt DateTime? @map(\"hesabfa_synced_at\")\n\n  paidAt      DateTime? @map(\"paid_at\")\n  shippedAt   DateTime? @map(\"shipped_at\")\n  deliveredAt DateTime? @map(\"delivered_at\")\n  createdAt   DateTime  @default(now()) @map(\"created_at\")\n  updatedAt   DateTime  @updatedAt @map(\"updated_at\")\n\n  user           User           @relation(fields: [userId], references: [id])\n  address        Address        @relation(fields: [addressId], references: [id])\n  shippingOption ShippingOption @relation(fields: [shippingOptionId], references: [id])\n  coupon         DiscountCode?  @relation(fields: [discountCodeId], references: [id], onDelete: SetNull)\n  items          OrderItem[]\n  survey         OrderSurvey?\n\n  @@index([userId])\n  @@index([status])\n  @@index([paymentStatus])\n  @@index([createdAt])\n  @@index([discountCodeId])\n  @@index([hesabfaCode])\n  @@map(\"orders\")\n}\n\nmodel OrderItem {\n  id        String @id @default(cuid())\n  orderId   String @map(\"order_id\")\n  productId String @map(\"product_id\")\n\n  // ── Immutable purchase snapshot ───────────────────────────────────────────\n  productName     String  @map(\"product_name\")\n  productSku      String  @map(\"product_sku\")\n  /// Unit list price frozen at order time, before any line discount.\n  priceAtPurchase BigInt  @map(\"price_at_purchase\")\n  /// Percentage discount applied to this line (0–100) — e.g. the wholesale /\n  /// cash discount on a partner invoice. 0 for plain retail lines. The net unit\n  /// price is priceAtPurchase × (1 − discountPct / 100).\n  discountPct     Decimal @default(0) @map(\"discount_pct\") @db.Decimal(5, 2)\n  /// Tax portion of this line item (e.g. VAT on priceAtPurchase × quantity)\n  taxAmount       BigInt  @default(0) @map(\"tax_amount\")\n  quantity        Int\n\n  order   Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  product Product @relation(fields: [productId], references: [id])\n\n  @@index([orderId])\n  @@index([productId])\n  @@map(\"order_items\")\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// PARTNER DASHBOARD\n// ─────────────────────────────────────────────────────────────────────────────\n\n/// Two-way support thread between a partner and the shop's support desk. A flat\n/// message log (not threaded): the dashboard groups it into Inbox (INBOUND),\n/// Sent (OUTBOUND) and Deleted (isDeleted) folders, with an unread badge on the\n/// inbox. Soft-deleted messages move to the Deleted folder and can be restored.\nmodel SupportMessage {\n  id          String           @id @default(cuid())\n  userId      String           @map(\"user_id\")\n  direction   MessageDirection\n  subject     String\n  body        String           @db.Text\n  /// Partner-side read flag (INBOUND messages in the partner inbox).\n  isRead      Boolean          @default(false) @map(\"is_read\")\n  /// Admin-side read flag for partner OUTBOUND messages in the admin inbox.\n  adminIsRead Boolean          @default(false) @map(\"admin_is_read\")\n  isDeleted   Boolean          @default(false) @map(\"is_deleted\")\n  createdAt   DateTime         @default(now()) @map(\"created_at\")\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, direction, isDeleted])\n  @@index([adminIsRead, direction, isDeleted])\n  @@map(\"support_messages\")\n}\n\n/// Post-purchase satisfaction survey — at most one per order («نظر سنجی»). The\n/// positive/negative points are stored as the selected option keys (the fixed\n/// option lists live in `src/lib/survey-options.ts`).\nmodel OrderSurvey {\n  id             String   @id @default(cuid())\n  orderId        String   @unique @map(\"order_id\")\n  userId         String   @map(\"user_id\")\n  /// 1–5 stars.\n  rating         Int\n  positivePoints String[] @map(\"positive_points\")\n  negativePoints String[] @map(\"negative_points\")\n  note           String?  @db.Text\n  createdAt      DateTime @default(now()) @map(\"created_at\")\n\n  order Order @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  user  User  @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"order_surveys\")\n}\n\n/// A saved, filtered price-list request the partner can download as a printable\n/// PDF («دریافت لیست قیمت»). The filter is snapshotted and the link is valid for\n/// ~24h (expiresAt); after that the partner regenerates it. Empty filter arrays\n/// mean \"all\" (all titles / brands / car models).\nmodel PriceListRequest {\n  id            String   @id @default(cuid())\n  userId        String   @map(\"user_id\")\n  /// Free-text product filters; fuzzy-matched against normalized name/SKU metadata. Empty = all.\n  titles        String[]\n  partsBrandIds Int[]    @map(\"parts_brand_ids\")\n  carModelIds   Int[]    @map(\"car_model_ids\")\n  createdAt     DateTime @default(now()) @map(\"created_at\")\n  expiresAt     DateTime @map(\"expires_at\")\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"price_list_requests\")\n}\n\n/// Wholesale partner suggestion to add a product to the shop catalogue\n/// (درخواست تأمین کالا). Admins review these in the communications panel.\nmodel ProductSuggestion {\n  id        String   @id @default(cuid())\n  userId    String   @map(\"user_id\")\n  /// Free-text description of the product the partner wants stocked.\n  body      String   @db.Text\n  /// Admin-side read flag for the communications inbox.\n  isRead    Boolean  @default(false) @map(\"is_read\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([isRead])\n  @@map(\"product_suggestions\")\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// DISCOUNT CODES / کد تخفیف\n// ─────────────────────────────────────────────────────────────────────────────\n\n/// Redeemable coupon managed in the admin panel («کد تخفیف»).\n/// Checkout application is wired separately; this model stores the code rules.\nmodel DiscountCode {\n  id   String @id @default(cuid())\n  /// Case-insensitive unique code the customer enters (stored uppercase).\n  code String @unique\n\n  type  DiscountType\n  /// Percent (0–100) or fixed Toman amount depending on `type`. Null for FREE_SHIPPING.\n  value Decimal?     @db.Decimal(12, 2)\n\n  startsAt DateTime  @map(\"starts_at\")\n  endsAt   DateTime? @map(\"ends_at\")\n\n  scopeType DiscountScopeType @default(CATEGORY) @map(\"scope_type\")\n  /// Target ids for `scopeType`. Empty = applies to all products.\n  scopeIds  String[]          @default([]) @map(\"scope_ids\")\n\n  /// Who may redeem this code: retail, wholesale, or both.\n  targetUserType DiscountTargetUserType @default(BOTH) @map(\"target_user_type\")\n\n  /// Max redemptions per customer. Null = unlimited.\n  perCustomerLimit Int? @map(\"per_customer_limit\")\n  /// Max total redemptions across all customers. Null = unlimited.\n  totalUsageLimit  Int? @map(\"total_usage_limit\")\n  /// How many times this code has been successfully redeemed.\n  usedCount        Int  @default(0) @map(\"used_count\")\n\n  /// Minimum cart subtotal (Toman) required to apply the code.\n  minCartAmount     BigInt? @map(\"min_cart_amount\")\n  /// Cap on the discounted amount in Toman (mainly for PERCENTAGE).\n  maxDiscountAmount BigInt? @map(\"max_discount_amount\")\n  /// When true, only customers with zero prior successful orders may use it.\n  firstOrderOnly    Boolean @default(false) @map(\"first_order_only\")\n  /// Require at least this many prior completed/paid orders. Null = no requirement.\n  minPreviousOrders Int?    @map(\"min_previous_orders\")\n\n  isActive  Boolean  @default(true) @map(\"is_active\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  orders Order[]\n\n  @@index([isActive])\n  @@index([startsAt])\n  @@index([endsAt])\n  @@map(\"discount_codes\")\n}\n"
}

